<?php
namespace App\Support;
use App\Models\{Apprentice,User,Programme,Employer,TutorGroup,LearningTask,ApprenticeSetupCase as SetupCase};
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class CohortSetup {
 public const ISSUES=['identity'=>'Identity needs checking','account'=>'Account and mailbox','staffing'=>'Staff responsibilities','dates'=>'Training dates','programme'=>'Programme or group mapping','employer'=>'Employer context','tasks'=>'Task workspace/source'];
 private static function fail(string $m='Profile, setup source or case changed. Reload before saving.'):never {throw ValidationException::withMessages(['setup_case'=>$m]);}
 public static function check(Apprentice $a):array {
  $a=Apprentice::findOrFail($a->id);$issues=[];$staff=[];$u=$a->user_id?User::find($a->user_id):null;$p=$a->programme_id?Programme::find($a->programme_id):null;$g=$a->tutor_group_id?TutorGroup::find($a->tutor_group_id):null;$e=$a->employer_id?Employer::find($a->employer_id):null;
  if(!preg_match('/^[A-Z0-9][A-Z0-9_-]{0,39}$/D',$a->reference)||Apprentice::whereRaw('UPPER(reference) = ?',[strtoupper($a->reference)])->count()!==1||($a->email&&Apprentice::whereRaw('LOWER(email) = ?',[strtolower(trim($a->email))])->count()>1)){$issues['identity']='Reference syntax/case or repeated individual email needs identity reconciliation.';}
  if(!$u||!$u->active||$u->role!=='apprentice'||!$u->email_verified_at||Apprentice::where('user_id',$u->id)->count()!==1||!filter_var($a->email,FILTER_VALIDATE_EMAIL)||strtolower(trim($a->email??''))!==strtolower(trim($u->email))||User::whereRaw('LOWER(email) = ?',[strtolower(trim($u->email))])->count()!==1){$issues['account']='Check individual email, current own account link and mailbox confirmation.';}
  $staffIssues=[];foreach(StaffHandover::SLOTS as$slot=>$label){$x=$a->{$slot.'_id'}?User::find($a->{$slot.'_id'}):null;$staff[$slot]=$x?StaffHandover::staffSeal($x):null;if(!$x||!StaffHandover::eligible($x,$slot)){$staffIssues[]=$label;}}if($staffIssues){$issues['staffing']='Check actual required assignments: '.implode(', ',$staffIssues).'. Missing optional duties are not automatic exemptions.';}
  if(!$a->start_date||!$a->planned_end_date||$a->planned_end_date->lessThan($a->start_date)){$issues['dates']='Known valid start/end dates are missing or inconsistent.';}
  if(!$p?->active||($a->tutor_group_id&&(!$g?->active||$g->programme_id!==$a->programme_id))){$issues['programme']='Check actual active programme/version and any assigned group mapping.';}
  if(!$e?->active){$issues['employer']='Employer link is missing/inactive; check actual employment or unemployment support context.';}
  $tasks=LearningTask::where('apprentice_id',$a->id)->orderBy('id')->get(['id','version','status','template']);$taskSeal=[];$pending=false;foreach($tasks as$t){$taskSeal[]=['id'=>$t->id,'version'=>$t->version,'status'=>$t->status,'template_hash'=>ReviewedImports::hash($t->template??[])];if(($t->template['kind']??'source-pending')==='source-pending'){$pending=true;}}
  if(!$tasks->count()||$pending){$issues['tasks']='No workspace or task source remains pending; check actual programme/cohort applicability before allocation/source changes.';}
  $hash=ReviewedImports::hash(['rules'=>'cohort-setup-v1','profile'=>$a->getAttributes(),'account'=>$u?->only(['id','name','email','active','role','record_version','auth_version','email_verified_at']),'programme'=>$p?->getAttributes(),'group'=>$g?->getAttributes(),'employer'=>$e?->getAttributes(),'staff'=>$staff,'tasks'=>$taskSeal]);
  return ['hash'=>$hash,'issues'=>$issues,'task_count'=>$tasks->count(),'meaning'=>'Operational setup flags only. All saved profiles are in scope unless filtered; not induction, funding, compliance, competence or Gateway approval.'];
 }
 public static function selected(array $filters):array {
  $q=Apprentice::query();foreach(['programme_id','tutor_group_id']as$field){if($filters[$field]??null){$q->where($field,(int)$filters[$field]);}}if($filters['start_from']??null){$q->whereDate('start_date','>=',$filters['start_from']);}if($filters['start_to']??null){$q->whereDate('start_date','<=',$filters['start_to']);}$search=trim($filters['search']??'');if($search!==''){$n='%'.str_replace(['!','%','_'],['!!','!%','!_'],mb_strtolower($search)).'%';$q->where(fn($q)=>$q->whereRaw("LOWER(reference) LIKE ? ESCAPE '!'",[$n])->orWhereRaw("LOWER(first_name) LIKE ? ESCAPE '!'",[$n])->orWhereRaw("LOWER(last_name) LIKE ? ESCAPE '!'",[$n]));}$people=$q->orderBy('last_name')->orderBy('id')->limit(1001)->get();if($people->count()>1000){self::fail('Narrow programme/group/start-date/search filters to at most1,000 profiles per read-only report.');}$counts=array_fill_keys(array_keys(self::ISSUES),0);$rows=[];
  foreach($people as$a){$position=self::check($a);foreach($position['issues']as$code=>$_){$counts[$code]++;}if(($filters['issue']??'all')!=='all'&&!isset($position['issues'][$filters['issue']])){continue;}$rows[]=['apprentice'=>$a,'position'=>$position,'cases'=>SetupCase::where('apprentice_id',$a->id)->get()->keyBy('issue')];}return ['rows'=>$rows,'matched_profiles'=>$people->count(),'counts'=>$counts];
 }
 public static function intact(SetupCase $c):bool {try{return isset(self::ISSUES[$c->issue])&&ReviewedImports::hash($c->details)===$c->details_hash&&$c->details['apprentice_id']===$c->apprentice_id&&$c->details['issue']===$c->issue&&$c->details['owner_id']===$c->owner_id&&$c->details['due_on']===$c->due_on->format('Y-m-d');}catch(\Throwable){return false;}}
 public static function position(SetupCase $c,Apprentice $a,?array $check=null):array {
  $check??=self::check($a);$flag=isset($check['issues'][$c->issue]);$verified=false;
  try{$p=$c->proof;$verified=self::intact($c)&&$p&&$c->decided_by&&$c->decided_at&&$p['state']===$c->state&&$p['version']===$c->version&&$p['details_hash']===$c->details_hash&&$p['source_hash']===$c->source_hash&&$p['source_hash']===$check['hash']&&$p['by']===$c->decided_by&&$p['at']===$c->decided_at->toIso8601String()&&$c->details['reference']===$a->reference;}catch(\Throwable){}
  $resolved=$verified&&$c->state==='Resolved'&&!$flag;$deferred=$verified&&$c->state==='Deferred'&&$flag;$withdrawn=$verified&&$c->state==='Withdrawn';$label=!self::intact($c)?'Evidence needs checking':($resolved?'Resolved against current source':($deferred?'Deferred; setup flag remains':($withdrawn?'Withdrawn from tracking; flags remain independent':($c->state==='Open'?'Open':($flag?'Flag present / needs recheck':'Decision source changed / needs recheck')))));
  return ['flag_present'=>$flag,'resolved'=>$resolved,'deferred'=>$deferred,'withdrawn'=>$withdrawn,'label'=>$label,'overdue'=>!$resolved&&!$withdrawn&&$c->due_on->lt(today()),'source_hash'=>$check['hash']];
 }
 private static function event(SetupCase $c,User $u,string $event,array $payload=[]):void {DB::table('apprentice_setup_case_events')->insert(['case_id'=>$c->id,'actor_id'=>$u->id,'event'=>$event,'payload'=>Crypt::encryptString(json_encode($payload,JSON_THROW_ON_ERROR)),'created_at'=>now()]);}
 private static function actor(User $u,int $auth):User {$u=User::whereKey($u->id)->lockForUpdate()->firstOrFail();abort_unless(LearningAccess::manager($u)&&$u->auth_version===$auth,403);return $u;}
 public static function save(User $actor,int $auth,Apprentice $profile,?SetupCase $record,int $version,string $source,array $data):SetupCase {
  return DB::transaction(function()use($actor,$auth,$profile,$record,$version,$source,$data):SetupCase {$m=self::actor($actor,$auth);$a=Apprentice::whereKey($profile->id)->lockForUpdate()->firstOrFail();$check=self::check($a);if(!hash_equals($check['hash'],$source)){self::fail();}$owner=User::whereKey($data['owner_id'])->lockForUpdate()->first();if(!$owner||!LearningAccess::manager($owner)){self::fail('Choose an active Administrator/CEO case owner.');}$c=$record?SetupCase::whereKey($record->id)->lockForUpdate()->firstOrFail():null;$issue=$c?->issue??$data['issue'];
   if(!isset(self::ISSUES[$issue])||(!$c&&!isset($check['issues'][$issue]))||(!$c&&SetupCase::where('apprentice_id',$a->id)->where('issue',$issue)->exists())||($c&&($c->apprentice_id!==$a->id||!self::intact($c)))||($c?->version??0)!==$version){self::fail('Use the current case/automatic flag; existing categories have one retained case.');}$before=$c?['details'=>$c->details,'state'=>$c->state,'proof'=>$c->proof,'source_hash'=>$c->source_hash]:null;$c??=new SetupCase(['apprentice_id'=>$a->id,'issue'=>$issue]);if(!$c->id){$c->id=(string)Str::uuid();}$details=['apprentice_id'=>$a->id,'issue'=>$issue,'reference'=>$a->reference,'owner_id'=>$owner->id,'due_on'=>$data['due_on'],'note'=>$data['note']];$c->owner_id=$owner->id;$c->due_on=$data['due_on'];$c->state='Open';$c->version=$version+1;$c->details=$details;$c->details_hash=ReviewedImports::hash($details);$c->source_hash=$source;$c->proof=null;$c->decided_by=null;$c->decided_at=null;$c->save();self::event($c,$m,'case_saved',['before'=>$before,'after'=>$details,'owner'=>$owner->id,'due'=>$data['due_on']]);return $c;
  },3);
 }
 public static function decide(User $actor,int $auth,SetupCase $record,int $version,string $source,string $decision,string $note):void {
  DB::transaction(function()use($actor,$auth,$record,$version,$source,$decision,$note):void {$m=self::actor($actor,$auth);$a=Apprentice::whereKey($record->apprentice_id)->lockForUpdate()->firstOrFail();$c=SetupCase::whereKey($record->id)->lockForUpdate()->firstOrFail();$check=self::check($a);if(!self::intact($c)||$c->version!==$version||!hash_equals($check['hash'],$source)||!in_array($decision,['resolve','defer','reopen','withdraw'],true)){self::fail();}$flag=isset($check['issues'][$c->issue]);if($decision==='resolve'&&($flag||$c->details['reference']!==$a->reference)){self::fail('Resolve only after the actual setup flag clears with the same checked learner identity.');}if($decision==='defer'&&(!$flag||$c->due_on->lt(today()))){self::fail('Deferral needs a present flag and current/future review date. It does not clear the flag.');}
   $before=['state'=>$c->state,'proof'=>$c->proof,'source_hash'=>$c->source_hash];$c->state=['resolve'=>'Resolved','defer'=>'Deferred','reopen'=>'Open','withdraw'=>'Withdrawn'][$decision];$c->version++;$c->source_hash=$source;$c->decided_by=$m->id;$c->decided_at=now()->setMicrosecond(0);$c->proof=$decision==='reopen'?null:['state'=>$c->state,'version'=>$c->version,'details_hash'=>$c->details_hash,'source_hash'=>$source,'by'=>$m->id,'at'=>$c->decided_at->toIso8601String(),'note'=>$note];$c->save();self::event($c,$m,'case_'.$decision,['before'=>$before,'note'=>$note]);
  },3);
 }
}
